const request = $('Webhook - HR Duyệt Thôi Việc').first().json;
const config = $json;
const headers = request.headers || {};
const suppliedSecret = String(headers['x-automation-secret'] || headers['X-Automation-Secret'] || '').trim();
if (!config.automationSecret || suppliedSecret !== String(config.automationSecret).trim()) throw new Error('Webhook thôi việc chưa được xác thực');
const body = request.body?.data || request.body || request;
const caseId = Number(body.caseId);
if (!Number.isInteger(caseId) || caseId <= 0) throw new Error('caseId hồ sơ thôi việc không hợp lệ');
return [{ json: { ...config, caseId, runId: String($execution.id) } }];

const response = $input.first().json;
const record = response.data ?? response;
const config = $('Xác thực yêu cầu từ hệ thống').first().json;
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const dateLabel = new Date(`${record.lastWorkingDate}T00:00:00+07:00`).toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: '2-digit', month: '2-digit', year: 'numeric' });
const employee = record.employee;
const employeeRecipient = String(config.testEmployeeEmail || employee.personalEmail || employee.workEmail || '').trim();
const itRecipient = String(config.testInternalEmail || config.itEmail || '').trim();
const accountingRecipient = String(config.testInternalEmail || config.accountingEmail || '').trim();
if (!employeeRecipient || !itRecipient || !accountingRecipient) throw new Error('Thiếu email nhận thông báo thôi việc');
const surveyUrl = record.exitSurveyUrl || config.exitSurveyUrl;
const assetNotes = record.assetNotes ? `<p><strong>Ghi chú tài sản:</strong> ${esc(record.assetNotes)}</p>` : '';
const itSubject = `[IT] Thu hồi thiết bị và tài khoản - ${employee.fullName}`;
const itHtml = `<h3>Yêu cầu IT xử lý thôi việc</h3><p>Nhân viên: <strong>${esc(employee.fullName)}</strong></p><p>Email công ty: ${esc(employee.workEmail)}</p><p>Phòng ban: ${esc(employee.departmentName)}</p><p>Ngày làm việc cuối: <strong>${dateLabel}</strong></p>${assetNotes}<ol><li>Thu hồi laptop, thẻ và thiết bị công ty.</li><li>Khóa email, VPN và các tài khoản nội bộ sau ngày làm việc cuối.</li><li>Sao lưu và bàn giao dữ liệu công việc.</li></ol>`;
const accountingSubject = `[Kế toán] Quyết toán thôi việc - ${employee.fullName}`;
const accountingHtml = `<h3>Yêu cầu quyết toán thôi việc</h3><p>Nhân viên: <strong>${esc(employee.fullName)}</strong></p><p>Phòng ban: ${esc(employee.departmentName)}</p><p>Ngày làm việc cuối: <strong>${dateLabel}</strong></p><p>Người duyệt: ${esc(record.approvedBy.fullName)}</p><ol><li>Tính lương đến ngày làm việc cuối.</li><li>Đối chiếu phép năm còn lại và các khoản tạm ứng.</li><li>Xác nhận quyết toán với bộ phận Nhân sự.</li></ol>`;
const farewellSubject = `Lời cảm ơn và khảo sát thôi việc - ${employee.fullName}`;
const farewellHtml = `<p>Kính gửi <strong>${esc(employee.fullName)}</strong>,</p><p>Cảm ơn bạn vì những đóng góp trong thời gian đồng hành cùng công ty. Chúc bạn nhiều thành công trên chặng đường tiếp theo.</p><p>Vui lòng dành ít phút hoàn thành khảo sát thôi việc để giúp chúng tôi cải thiện môi trường làm việc:</p><p><a href="${esc(surveyUrl)}">Mở khảo sát thôi việc</a></p><p>Trân trọng,<br/><strong>Bộ phận Nhân sự</strong></p>`;
const telegramText = `📋 <b>HỒ SƠ THÔI VIỆC ĐÃ ĐƯỢC DUYỆT</b>\n\nMã hồ sơ: <b>#${record.caseId}</b>\nNhân viên: <b>${esc(employee.fullName)}</b>\nPhòng ban: ${esc(employee.departmentName)}\nNgày làm việc cuối: <b>${dateLabel}</b>\n\nĐã chuyển tác vụ tới IT, Kế toán và chuẩn bị thư cảm ơn cho nhân viên.`;
return [{ json: { ...config, ...record, employeeRecipient, itRecipient, accountingRecipient, itSubject, itHtml, accountingSubject, accountingHtml, farewellSubject, farewellHtml, telegramText } }];

const source = $('Soạn nội dung điều phối bằng tiếng Việt').item.json;
const succeeded = (name, telegram = false) => {
  try {
    const result = $(name).item.json || {};
    if (result.error) return false;
    if (telegram) return result.ok !== false;
    return !Array.isArray(result.rejected) || result.rejected.length === 0;
  } catch { return false; }
};
const itNotified = succeeded('Gửi ticket cho phòng IT');
const financeNotified = succeeded('Gửi thông báo cho Kế toán');
const employeeNotified = succeeded('Gửi thư cảm ơn và khảo sát');
const telegramNotified = succeeded('Thông báo kênh liên phòng ban', true);
const successCount = [itNotified, financeNotified, employeeNotified, telegramNotified].filter(Boolean).length;
const status = successCount === 4 ? 'SENT' : successCount > 0 ? 'PARTIAL' : 'FAILED';
return [{ json: { ...source, itNotified, financeNotified, employeeNotified, telegramNotified, status, detail: `IT=${itNotified}; KeToan=${financeNotified}; NhanVien=${employeeNotified}; Telegram=${telegramNotified}` } }];
